200	// distillCache memoizes the fingerprint of each session that has been
201	// distilled, so an incremental run skips sessions whose transcript and
202	// checkpoint are unchanged.
203	type distillCache struct {
204		Version  int               `json:"version"`
205		Sessions map[string]string `json:"sessions"`
206	}
