208	func newDistillCommand(opts Options) *cobra.Command {
209		distillOpts := distillCommandOptions{agent: "auto", timeout: defaultDistillTimeout, maxChunkBytes: defaultDistillChunkSize, confidenceThreshold: defaultFactConfidenceThreshold, concurrency: defaultDistillConcurrency}
210		cmd := &cobra.Command{
211			Use:   "distill [path]",
212			Short: "Distill captured sessions into durable facts (agent-required)",
213			Args:  cobra.MaximumNArgs(1),
214			RunE: func(cmd *cobra.Command, args []string) error {
215				target := "."
216				if opts.Env.RepoRoot != "" {
217					target = opts.Env.RepoRoot
218				}
219				if len(args) == 1 {
220					target = args[0]
221				}
222				return runDistill(cmd.Context(), cmd, opts, distillOpts, target)
223			},
224		}
225		cmd.Flags().StringVar(&distillOpts.branch, "branch", "", "Limit distillation to a single branch (default: all exported branches)")
226		cmd.Flags().BoolVar(&distillOpts.force, "force", false, "Recompute all distilled facts from scratch instead of skipping unchanged sessions")
227		cmd.Flags().BoolVar(&distillOpts.json, "json", false, "Emit the fact source summary as JSON")
228		cmd.Flags().StringVar(&distillOpts.agent, "agent", "auto", "Distillation agent: auto, codex, claude-code, or command")
229		cmd.Flags().StringArrayVar(&distillOpts.agentCommand, "agent-command", nil, "Agent command argv for --agent command")
230		cmd.Flags().Float64Var(&distillOpts.confidenceThreshold, "confidence", defaultFactConfidenceThreshold, "Minimum agent confidence to auto-apply a merge/supersede; below this it is queued for review")
231		cmd.Flags().StringVar(&distillOpts.model, "model", "", "Override the agent model for codex/claude-code (e.g. a fast/cheap model like gpt-5.4-mini)")
232		cmd.Flags().StringVar(&distillOpts.effort, "effort", "", "Override the reasoning effort for codex/claude-code (e.g. low) — pairs with --model for a cheap run")
233		cmd.Flags().IntVar(&distillOpts.concurrency, "concurrency", defaultDistillConcurrency, "Distill agent calls to run in flight at once (1 = strictly sequential; higher values may add one concurrent reconcile call)")
234		return cmd
235	}
