237	func runDistill(ctx context.Context, cmd *cobra.Command, opts Options, distillOpts distillCommandOptions, target string) error {
238		repoDir, local, err := resolveLocalTargetRepoDir(ctx, opts.Runner, target)
239		if err != nil {
240			return err
241		}
242		if !local {
243			return fmt.Errorf("distill requires a local repository path: %s", target)
244		}
245		storage, err := repoStoragePaths(ctx, opts.Runner, opts.Env, repoDir)
246		if err != nil {
247			return err
248		}
249		if distillOpts.agent == "auto" {
250			distillOpts.agent = defaultRefreshAgent(ctx, opts.Runner, repoDir)
251		}
252		if distillOpts.agent == "none" {
253			return errors.New("distillation requires an agent (codex or claude-code); none found on PATH")
254		}
255		if distillOpts.run == nil {
256			distillOpts.run = execDistillAgent
257		}
258		// Progress goes to stderr so it never corrupts the --json summary on stdout.
259		progress := newProgress(cmd.ErrOrStderr(), "distill")
260		task := progress.Begin("distill sessions")
261		distillOpts.progress = func(p distillProgress) {
262			task.Update(distillProgressLabel(p))
263		}
264		source, err := runDistillForBrain(ctx, repoDir, storage.BrainDir, distillOpts, opts.Now().UTC())
265		task.Finish(err)
266		if err != nil {
267			return err
268		}
269		if distillOpts.json {
270			data, err := json.MarshalIndent(source, "", "  ")
271			if err != nil {
272				return err
273			}
274			fmt.Fprintln(cmd.OutOrStdout(), string(data))
275			return nil
276		}
277		fmt.Fprintf(cmd.OutOrStdout(), "distilled %d facts (%d distilled, %d authored, %d superseded) across %d branch(es) from %d chunks; %d proposals queued for review\n",
278			source.Facts, source.Distilled, source.Authored, source.Superseded, len(source.Branches), source.ChunksScanned, source.Proposals)
279		return nil
280	}
