282	// distillProgressLabel renders a distillProgress as a refresh-style line, e.g.
283	// "distill sessions 12/55 done (main), 87 facts found". The count is deliberately
284	// NOT preceded by ": " so the label does not match progressCountPattern: distill
285	// reports once per session (coarse granularity), and matching that pattern would
286	// let the non-TTY throttle collapse same-fact-count sessions into a single status
287	// and suppress per-session lines. (Guarded by TestDistillProgressLabelNotThrottled.)
288	func distillProgressLabel(p distillProgress) string {
289		label := "distill sessions"
290		if p.SessionsTotal <= 0 {
291			return label
292		}
293		label += fmt.Sprintf(" %d/%d done", p.SessionsDone, p.SessionsTotal)
294		if p.Branch != "" {
295			label += " (" + p.Branch + ")"
296		}
297		return label + fmt.Sprintf(", %s found", pluralCount(p.Facts, "fact"))
298	}
