300	// runDistillForBrain is the agent-driven distillation engine, operating on an
301	// already-exported brain directory. It enumerates sessions chronologically,
302	// chunks each transcript, runs the agent per chunk, merges the resulting facts
303	// into per-branch stores, and records the fact source on the brain manifest.
304	// repoDir is the working directory the agent runs in (sandboxed read-only).
305	func runDistillForBrain(ctx context.Context, repoDir, brainDir string, distillOpts distillCommandOptions, now time.Time) (*factSourceManifest, error) {
306		manifest, err := loadBrainManifest(brainDir)
307		if err != nil {
308			return nil, err
309		}
310		if manifest.Sources == nil || manifest.Sources.Sessions == nil || len(manifest.Sources.Sessions.Sessions) == 0 {
311			return nil, errors.New("no exported sessions; run `entire brain refresh` first")
312		}
313		if distillOpts.run == nil {
314			return nil, errors.New("distill: no agent runner configured")
315		}
316		if distillOpts.maxChunkBytes <= 0 {
317			distillOpts.maxChunkBytes = defaultDistillChunkSize
318		}
319	
320		taxonomy, err := loadFactTaxonomy(brainDir, now)
321		if err != nil {
322			return nil, err
323		}
324		prompt, err := renderDistillPrompt(taxonomy)
325		if err != nil {
326			return nil, err
327		}
328		args, err := distillAgentCommandArgs(distillOpts.agent, distillOpts.agentCommand, prompt)
329		if err != nil {
330			return nil, err
331		}
332		reconcileArgs, err := distillAgentCommandArgs(distillOpts.agent, distillOpts.agentCommand, reconcilePrompt())
333		if err != nil {
334			return nil, err
335		}
336		// Pin the agent model + effort when set, so distill AND reconcile run on the same
337		// (cheap) model. Both are no-ops when empty.
338		args = injectAgentEffort(injectAgentModel(args, distillOpts.agent, distillOpts.model), distillOpts.agent, distillOpts.effort)
339		reconcileArgs = injectAgentEffort(injectAgentModel(reconcileArgs, distillOpts.agent, distillOpts.model), distillOpts.agent, distillOpts.effort)
340		threshold := distillOpts.confidenceThreshold
341		if threshold <= 0 {
342			threshold = defaultFactConfidenceThreshold
343		}
344	
345		sessions := append([]exportSession(nil), manifest.Sources.Sessions.Sessions...)
346		// Chronological order so any future supersession chain reconstructs
347		// deterministically regardless of incremental vs --force.
348		sort.SliceStable(sessions, func(i, j int) bool { return sessions[i].CreatedAt.Before(sessions[j].CreatedAt) })
349	
350		prevCache := loadDistillCache(brainDir)
351		newCache := distillCache{Version: distillCacheVersion, Sessions: make(map[string]string, len(sessions))}
352	
353		byBranch := map[string][]factRecord{}
354		proposalsByBranch := map[string][]factProposal{}
355		loaded := map[string]bool{}
356		// dirtyBranches tracks branches whose in-memory facts/proposals have
357		// diverged from disk since the last successful flush, so a flush rewrites
358		// only what changed instead of re-marshaling every loaded branch's full
359		// store every interval.
360		dirtyBranches := map[string]bool{}
361		var warnings []string
362		chunksScanned, chunksDistilled := 0, 0
363	
364		// resolveBranch maps a session to the branch its facts are written under,
365		// falling back to the manifest default (then distillDefaultBranch) when the
366		// session's branch field is empty. The --branch filter must compare against
367		// this resolved value, not session.Branch, so sessions with an empty branch
368		// are not silently excluded from a `--branch <default>` run.
369		resolveBranch := func(session exportSession) string {
370			branch := session.Branch
371			if branch == "" {
372				branch = strings.TrimSpace(manifest.DefaultBranch)
373			}
374			if branch == "" {
375				branch = distillDefaultBranch
376			}
377			return branch
378		}
379	
380		// Denominator for progress: sessions that pass the branch filter. Cached
381		// (unchanged) sessions still advance the counter so the line reaches N/N.
382		totalSessions := 0
383		for _, session := range sessions {
384			if distillOpts.branch != "" && resolveBranch(session) != distillOpts.branch {
385				continue
386			}
387			totalSessions++
388		}
389		sessionsDone, factsFound := 0, 0
390		// Track agent-call outcomes so a misconfiguration that fails every call (e.g.
391		// an invalid --model) aborts fast with the agent's own error, instead of
392		// silently churning through every session reporting "0 facts found".
393		agentFailures, anyAgentSuccess := 0, false
394	
395		// ensureBranch lazily loads a branch's existing facts. On --force the
396		// previously distilled facts are dropped so they are rebuilt from scratch;
397		// authored facts are always preserved.
398		ensureBranch := func(branch string) {
399			if loaded[branch] {
400				return
401			}
402			existing, loadErr := loadFacts(brainDir, branch)
403			if loadErr != nil {
404				warnings = append(warnings, fmt.Sprintf("load facts for %s: %v", branch, loadErr))
405			}
406			if distillOpts.force {
407				kept := existing[:0]
408				for _, record := range existing {
409					if record.Origin != factOriginDistilled {
410						kept = append(kept, record)
411					}
412				}
413				existing = kept
414				// The in-memory store now differs from disk; the rebuild must be
415				// written out even if the branch gains no new facts.
416				dirtyBranches[branch] = true
417			}
418			byBranch[branch] = existing
419			loaded[branch] = true
420		}
421	
422		// flushFactStores persists the in-memory distill state — dirty branches'
423		// facts and proposals, plus the session cache — so a killed or crashed run
424		// resumes from the last flush instead of losing everything (a distill run is
425		// hours of agent calls; the original write-once-at-the-end design lost the
426		// entire run on any interruption). Facts are idempotent across a resume: ids are
427		// content-derived and reconcile merges near-duplicates, so re-distilling the
428		// partially-flushed session at the kill point is safe. A mid-run (non-final)
429		// cache write keeps prevCache entries for sessions not yet visited — dropping
430		// manifest-removed sessions is the final write's job, and dropping unvisited
431		// entries mid-run would force a needless full re-distill of them after a
432		// restart. Under --force the opposite holds: ensureBranch has already dropped
433		// the unvisited sessions' distilled facts from byBranch, so persisting their
434		// still-matching prevCache fingerprints alongside the truncated fact store
435		// would make a plain rerun after a kill skip those sessions forever — their
436		// facts silently lost. A force run therefore writes newCache only, and an
437		// interrupted force run re-distills the sessions it never reached.
438		flushFactStores := func(final bool) error {
439			for branch := range dirtyBranches {
440				if err := writeFacts(brainDir, branch, byBranch[branch]); err != nil {
441					return err
442				}
443				// Union this run's proposals with any already queued. Re-loading on
444				// every flush is idempotent: earlier flushes' proposals come back as
445				// priors and dedupe away. A --force rebuild starts fresh (it rebuilds
446				// the distilled facts), but drops the prior backlog only on the FINAL
447				// flush — a mid-run flush that skipped priors would wipe the review
448				// queue ~50 calls in, and a kill there would lose it before the
449				// rebuild produced its replacement.
450				var prior []factProposal
451				if !(distillOpts.force && final) {
452					if loadedProposals, loadErr := loadFactProposals(brainDir, branch); loadErr != nil {
453						warnings = append(warnings, fmt.Sprintf("load proposals for %s: %v", branch, loadErr))
454					} else {
455						prior = loadedProposals
456					}
457				}
458				merged := dedupeProposals(append(prior, proposalsByBranch[branch]...))
459				if err := writeFactProposals(brainDir, branch, merged); err != nil {
460					return err
461				}
462				// A force run keeps branches dirty between mid-run flushes so the
463				// final flush always rewrites them — that write is what drops the
464				// prior proposal backlog. Otherwise the branch is clean until new
465				// fact actions touch it.
466				if final || !distillOpts.force {
467					delete(dirtyBranches, branch)
468				}
469			}
470			cache := newCache
471			if !final && !distillOpts.force {
472				cache = distillCache{Version: distillCacheVersion, Sessions: make(map[string]string, len(prevCache.Sessions)+len(newCache.Sessions))}
473				for id, fingerprint := range prevCache.Sessions {
474					cache.Sessions[id] = fingerprint
475				}
476				for id, fingerprint := range newCache.Sessions {
477					cache.Sessions[id] = fingerprint
478				}
479			}
480			saveDistillCache(brainDir, cache)
481			return nil
482		}
483		flushInterval := distillOpts.flushEvery
484		if flushInterval <= 0 {
485			flushInterval = distillFlushCallInterval
486		}
487		callsSinceFlush := 0
488		maybeFlush := func() {
489			if callsSinceFlush < flushInterval {
490				return
491			}
492			// Reset even on failure so a persistent write error is retried once per
493			// interval, not on every call.
494			callsSinceFlush = 0
495			if err := flushFactStores(false); err != nil {
496				// Non-fatal: a mid-run flush only narrows the loss window, and
497				// aborting an hours-long run over a transient write error would lose
498				// far more than the flush protects. Failed branches stay dirty, so
499				// the next interval (and the final flush) retries them.
500				warnings = append(warnings, fmt.Sprintf("mid-run flush failed (will retry): %v", err))
501			}
502		}
503	
504		for _, session := range sessions {
505			branch := resolveBranch(session)
506			if distillOpts.branch != "" && branch != distillOpts.branch {
507				// Carry the session's cache entry through unchanged: the final flush
508				// persists newCache only, so dropping filtered sessions here would
509				// make the next unfiltered run re-distill every other branch from
510				// scratch. (The fingerprint-match skip below does the same.)
511				if prev, ok := prevCache.Sessions[session.SessionID]; ok {
512					newCache.Sessions[session.SessionID] = prev
513				}
514				continue
515			}
516			ensureBranch(branch)
517	
518			sessionsDone++
519			// Report once per session, at every exit path, so the running fact count
520			// includes the session just processed (an emit at session start would lag
521			// by one session and always show 0 for a single-session run).
522			reportProgress := func() {
523				if distillOpts.progress != nil {
524					distillOpts.progress(distillProgress{SessionsDone: sessionsDone, SessionsTotal: totalSessions, Branch: branch, Facts: factsFound})
525				}
526			}
